import sqlite3, json
conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row
# Search for CI-0011
for table in ['order_items', 'rt_variants', 'products', 'orders']:
    try:
        rows = conn.execute(f'SELECT * FROM {table}').fetchall()
        for r in rows:
            row_str = json.dumps({k: r[k] for k in r.keys()})
            if 'CI-0011' in row_str or 'Northline' in row_str or 'gift_wrap' in row_str or 'gift wrap' in row_str.lower():
                print(f'{table}: {row_str}')
    except Exception as e:
        print(f'{table}: {e}')
conn.close()
"

